\begin{tikzpicture}[x=1.8cm,y=0.65cm,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\foreach \d/\last in {1/1,2/3,3/7,4/15}{
\foreach \j in {0,...,\last}{
\pgfmathsetmacro{\yy}{8-(\j+0.5)*16/pow(2,\d)}
\pgfmathsetmacro{\py}{8-(floor(\j/2)+0.5)*16/pow(2,\d-1)}
\pgfmathtruncatemacro{\bit}{mod(\j,2)}
\ifnum\bit=0
\draw[black,line width=0.8pt] ({\d-1},\py)--(\d,\yy) node[pos=0.58,above=1pt,sloped,inner sep=0pt] {H};
\else
\draw[black,line width=0.8pt] ({\d-1},\py)--(\d,\yy) node[pos=0.58,below=1pt,sloped,inner sep=0pt] {T};
\fi
}}
\end{tikzpicture}
